import{_ as n,l as i,o as a,c as l,v as o,p as s,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"引用计数 GC","description":"","frontmatter":{"title":"引用计数 GC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/refcounting-gc.md","filePath":"cs/refcounting-gc.md","lastUpdated":1789023840000}'),h={name:"cs/refcounting-gc.md"};function f(C,e,_,u,m,E){const t=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="引用计数-gc" tabindex="-1">引用计数 GC <a class="header-anchor" href="#引用计数-gc" aria-label="Permalink to &quot;引用计数 GC&quot;">​</a></h1><div class="epigraph"><p>每个对象记有多少指针指向它，到零则释放。及时，但循环会泄漏，除非配合循环检测或弱引用；更新计数的原子开销在多核上显著。</p><footer>—— 据 Collins, A Method for Overlapping and Erasure of Lists, 1960；Jones 手册；对照[线性类型](/cs/linear-ownership) 整理</footer></div><p>上一课<a href="/cs/copying-gc">复制式</a> 靠追踪。缺口是 <strong>RC</strong>：赋值时减旧加新。Python、Swift（ARC）、部分 Rust <code>Rc</code>。本课钉循环与原子，写屏障下一课是追踪式的。不把 RC 当线性类型——线性是静态零计数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>追踪有暂停；RC 希望即时回收。循环：<code>a.p=b; b.p=a</code> 计数永不为零。解决：周期检测、或禁止循环（所有权树）、或弱引用打破。缺口是<strong>计数协议</strong>，不是 Cheney 扫描。</p><p>多线程：计数更新要原子或缓冲（如 Cobsen 的缓冲 RC）。</p><h3 id="rc-不是-malloc-free-手工配对" tabindex="-1">RC 不是 malloc/free 手工配对 <a class="header-anchor" href="#rc-不是-malloc-free-手工配对" aria-label="Permalink to &quot;RC 不是 malloc/free 手工配对&quot;">​</a></h3><p>程序员不写 free；赋值重载负责。但循环与性能仍是实现问题。C++ <code>shared_ptr</code> 循环同样漏。</p><p><span class="marginnote">Collins 1960。Bacon、Rajan 等循环回收。Swift ARC。Jones 手册 RC 章。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写指针槽：<code>decref(old); incref(new)</code>。零则跑析构再释放。优化：局部变量可省略（编译器 RC 消除，类似线性）。</p>',11)),(a(),s(p,null,{default:r(()=>[d(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASG%5B%22%E6%8C%87%E9%92%88%E8%B5%8B%E5%80%BC%22%5D%20--%3E%20DEC%5B%22%E6%97%A7%E8%AE%A1%E6%95%B0%20-1%22%5D%0A%20%20ASG%20--%3E%20INC%5B%22%E6%96%B0%E8%AE%A1%E6%95%B0%20%2B1%22%5D%0A%20%20DEC%20--%3E%20Z%5B%22%E5%88%B0%200%20%E5%88%99%E6%9E%90%E6%9E%84%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与复制：有的系统幼代追踪、老年代 RC，点名。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>原子：<code>increment</code> 争用热对象。缓冲：把 RC 操作记入线程本地，批量。不要在析构里再形成复杂图而不重入。</p><p>与<a href="/cs/null-option">Option</a>：空指针不 incref。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写写屏障卡表。后课默认：RC 及时但不收循环。下一课写屏障与卡表——追踪分代用。</p><p>也不把 RC 当文件系统链接计数课（思想类似，对象不同）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RC：赋值维护计数，零则释放。</li><li>循环需额外机制；多核要原子或缓冲。</li><li>与静态线性类型不同层。</li><li>出处：Collins, 1960；Jones 手册；对照 Bacon 等。</li></ul>',9))])}const R=n(h,[["render",f]]);export{A as __pageData,R as default};
